// Viento desde la API IAGRO (/forecast/hourly)
// Hoy y mañana: detalle por horario + link al radar
// Campos por horario: h (hora), vsd (km/h), vdId (de dónde viene: N, NE...), vd45 (grados), vg (ráfaga km/h o null)
const data = $json.data || [];
const ctx = $('Adjuntar Datos de Usuario').first().json;
const usuario = ctx.usuario || {};
const conversationId = $('Webhook').item.json.body.conversation.id;
const finca = usuario.nombre_propiedad || 'tu campo';

// ===== Ajustes =====
const DIAS_DETALLE = 2;     // hoy + mañana con cada horario
const MAX_BOTONES = 1000;   // WhatsApp rechaza botones si el texto supera 1024

const r = (v) => Math.round(Number(v) || 0);
const num = (v) => (v === null || v === undefined || v === '') ? null : Number(v);
const NOMBRES = { N: 'Norte', NE: 'Noreste', E: 'Este', SE: 'Sureste', S: 'Sur', SO: 'Suroeste', O: 'Oeste', NO: 'Noroeste' };
const PUNTOS = ['N', 'NE', 'E', 'SE', 'S', 'SO', 'O', 'NO'];
// La flecha indica HACIA dónde sopla (viento del Norte empuja hacia el Sur → ↓)
const FLECHAS = { N: '↓', NE: '↙', E: '←', SE: '↖', S: '↑', SO: '↗', O: '→', NO: '↘' };
const norm = (g) => ((Number(g) || 0) % 360 + 360) % 360;
const puntoDe = (g) => PUNTOS[Math.round(norm(g) / 45) % 8];
const nivel = (v, g) => (v >= 35 || g >= 60) ? '🔴' : (v >= 20 || g >= 45) ? '🟠' : v >= 10 ? '🟡' : '🟢';

const DIAS = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
const etiquetaDia = (fecha, i) => {
  const [dd, mm, aa] = fecha.split('/');
  const ddmm = `${dd}/${mm}`;
  return i === 0 ? `Hoy ${ddmm}` : i === 1 ? `Mañana ${ddmm}` : `${DIAS[new Date(aa, mm - 1, dd, 12).getDay()]} ${ddmm}`;
};

const dias = data.slice(0, DIAS_DETALLE).map((dia, i) => ({
  etiqueta: etiquetaDia(dia.fecha, i),
  paso: dia.granularidad_horas || 1,
  filas: (dia.horarios || [])
    .filter(h => num(h.vsd) !== null)
    .map(h => ({ h: h.h, v: num(h.vsd), g: num(h.vg), dir: h.vdId || puntoDe(h.vd45), grados: h.vd45 ?? null }))
})).filter(d => d.filas.length);

if (!dias.length) {
  return [{ json: { conversation_id: conversationId, content: '⚠️ No hay datos de viento disponibles en este momento. Intenta nuevamente en unos minutos. 🙏' } }];
}

// ===== Encabezado =====
const ahora = dias[0].filas[0];
const encabezado = `💨 *Viento — ${finca}*\n\n` +
  `🌬️ *Ahora (${ahora.h}):* ${r(ahora.v)} km/h del ${NOMBRES[ahora.dir] || ahora.dir}` +
  `${ahora.grados !== null ? ` (${r(ahora.grados)}°)` : ''} ${FLECHAS[ahora.dir] || ''}` +
  `${ahora.g !== null ? ` · ráfagas ${r(ahora.g)} km/h` : ''}`;

// ===== Detalle (hoy + mañana) =====
const detalle = dias.map(d =>
  `📅 *${d.etiqueta}*${d.paso > 1 ? ` _(cada ${d.paso} h)_` : ''}\n` +
  d.filas.map(f => `${f.h} ${nivel(f.v, f.g ?? 0)} ${r(f.v)} km/h del ${f.dir} ${FLECHAS[f.dir] || ''}${f.g !== null ? ` · ráf ${r(f.g)}` : ''}`).join('\n')
).join('\n\n');

const leyenda = `🟢 <10 · 🟡 10–20 · 🟠 20–35 · 🔴 >35 km/h\n_“del S” = de dónde viene · flecha = hacia dónde sopla_`;
const botones = {
  content_type: 'input_select',
  content_attributes: {
    items: [
      { title: '💨 ¿Puedo fumigar?', value: 'fumigar' },
      { title: '🚨 Alertas', value: 'alertas' },
      { title: '📋 Ver menú', value: 'menu' }
    ]
  }
};
const conBotones = (content) => content.length <= MAX_BOTONES ? { content, ...botones } : { content };

const radar = `🌐 Radar en vivo: https://iagro360.xyz/radar/${usuario.id}`;

// Detalle 48 h + radar. Si no entra en el límite de WhatsApp para botones, se quita la leyenda
const completo = `${encabezado}\n\n${detalle}\n\n${leyenda}\n\n${radar}`;
const corto = `${encabezado}\n\n${detalle}\n\n${radar}`;
return [{ json: { conversation_id: conversationId, ...conBotones(completo.length <= MAX_BOTONES ? completo : corto) } }];

// Mensajes de la campaña FERIA (nombre en Configuración Global → feria_nombre)
// Llega desde "Consultar Clima Feria (API)" (con $json.data) o directo desde el IF (sin clima)
const ctx = $('Adjuntar Datos de Usuario').first().json;
const cfg = $('Configuración Global').first().json;
const conversationId = $('Webhook').first().json.body.conversation.id;
const intent = ctx.intent;
const data = $json.data || [];
const registrado = !!ctx.usuario?.id;
const feria = cfg.feria_nombre || 'Agro Vidas';

const nombre = String(ctx.contact_name || '').split(' ')[0] || 'productor';
const codigo = `AV${String(ctx.telefono || '').slice(-6)}`;
const r = (v) => Math.round(Number(v) || 0);
const n = (v) => Number(v) || 0;
const fmtMm = (mm) => mm <= 0 ? '0' : mm >= 1 ? String(Math.round(mm)) : (Math.round(mm * 10) / 10).toFixed(1);
const radarUrl = (lat, lon) => `https://www.ventusky.com/?p=${Number(lat).toFixed(3)};${Number(lon).toFixed(3)};9&l=rain-3h`;
const mapsUrl = (lat, lon) => `https://www.google.com/maps/search/?api=1&query=${lat},${lon}`;
const DIAS = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
const diaSemana = (f) => { const [d, m, a] = f.split('/'); return DIAS[new Date(a, m - 1, d, 12).getDay()]; };
const json = (txt, def) => { try { return JSON.parse(txt || ''); } catch (e) { return def; } };

const msg = (content, items) => ({
  json: {
    conversation_id: conversationId,
    content,
    ...(items ? { content_type: 'input_select', content_attributes: { items } } : {})
  }
});

// WhatsApp: máximo 3 botones y 20 caracteres por título
const BOTONES_FERIA = [
  { title: '🧭 Guía de la feria', value: 'guia' },
  { title: '🌤️ Clima feria', value: 'clima feria' },
  { title: '👥 Invitar amigo', value: 'invitar' }
];
const otrosBotones = (excluir) => BOTONES_FERIA.filter(b => b.value !== excluir);

// ---------- Próximas 24 h (/forecast/next24h) ----------
const resumen24h = () => {
  const tds = data.map(h => n(h.temperatura_c));
  return {
    ahora: data[0] || {},
    proxima: data[1] || data[0] || {},
    mm: data.reduce((s, h) => s + n(h.precipitacion_mm), 0),
    prob: Math.max(0, ...data.map(h => n(h.probabilidad_precipitacion))),
    tmin: Math.min(...tds), tmax: Math.max(...tds)
  };
};
const vientoTxt = (h) => `${r(h.velocidad_viento_kmh)} km/h ${h.direccion_viento || ''}${h.rafaga_kmh != null ? ` (ráf. ${r(h.rafaga_kmh)})` : ''}`;

// =====================================================
// 1) FERIA: bienvenida + clima de los 2 días + pedir ubicación
// =====================================================
if (intent === 'feria') {
  const hoy = data[0]?.fecha;
  const finGratis = (hoy ? DateTime.fromFormat(hoy, 'dd/MM/yyyy') : $now).plus({ months: 1 }).toFormat('dd/LL');

  const statsDia = (dia) => {
    const hs = dia.horarios || [];
    const diurnas = hs.filter(h => { const x = Number(String(h.h).slice(0, 2)); return x >= 8 && x <= 20; });
    const base = diurnas.length ? diurnas : hs;
    const tds = hs.map(h => n(h.td));
    const frec = {};
    base.forEach(h => { if (h.vdId) frec[h.vdId] = (frec[h.vdId] || 0) + 1; });
    return {
      tmin: Math.min(...tds), tmax: Math.max(...tds),
      prob: Math.max(0, ...hs.map(h => n(h.rp))),
      mm: hs.reduce((s, h) => s + n(h.sr), 0),
      viento: r(base.reduce((s, h) => s + n(h.vsd), 0) / (base.length || 1)),
      rafaga: Math.max(0, ...base.map(h => n(h.vg))),
      dir: Object.entries(frec).sort((a, b) => b[1] - a[1])[0]?.[0] || '',
      lluviaDesde: base.find(h => n(h.rp) >= 50)?.h
    };
  };

  const consejo = (s) => {
    if (s.lluviaDesde) return `☔ lluvia desde ${s.lluviaDesde}`;
    if (s.mm >= 2 || s.prob >= 40) return '🌦️ llevá paraguas';
    if (s.rafaga >= 45 || s.viento >= 25) return '💨 ventoso';
    if (s.tmax >= 33) return '🥵 calor, llevá agua';
    if (s.tmin <= 12) return '🧥 llevá abrigo';
    return '☀️ ideal para recorrer';
  };

  const lineas = [cfg.feria_dia1, cfg.feria_dia2].map(fecha => {
    const dia = data.find(d => d.fecha === fecha);
    if (!dia || !(dia.horarios || []).length) return null;
    const s = statsDia(dia);
    return `*${fecha === hoy ? 'Hoy' : diaSemana(fecha)} ${fecha.slice(0, 2)}:* ${r(s.tmin)}–${r(s.tmax)}° · 🌧️${r(s.prob)}% · 💨${s.viento} ${s.dir}\n${consejo(s)}`;
  }).filter(Boolean);

  return [
    msg(
      `🌱 ¡Hola *${nombre}*! Bienvenido a iAgro en *${feria} 2026* 🎪\n` +
      `🎁 Tu mes gratis está activo hasta el *${finGratis}*\n\n` +
      (lineas.length ? `🌤️ *Clima en la feria*\n${lineas.join('\n')}\n\n` : '') +
      `📡 Radar: ${radarUrl(cfg.feria_lat, cfg.feria_lon)}`
    ),
    msg(
      `📍 *Enviame la ubicación de tu lote* y te doy su pronóstico exacto.\n` +
      `👉 Tocá 📎 → Ubicación → mové el pin a tu campo.`,
      [
        { title: '📋 Elegir mi zona', value: 'elegir mi zona' },
        { title: '🧭 Guía de la feria', value: 'guia' }
      ]
    )
  ];
}

// =====================================================
// 2) LISTA DE ZONAS (respaldo si no sabe enviar la ubicación)
// =====================================================
if (intent === 'feria_zonas') {
  return [msg(
    '📋 Elegí la zona de tu lote:',
    json(cfg.feria_zonas, []).slice(0, 10).map(z => ({ title: z.nombre, value: z.nombre }))
  )];
}

// =====================================================
// 3) CONFIRMACIÓN DEL LOTE (ubicación o zona) + promo
// =====================================================
if (intent === 'ubicacion' || intent === 'feria_zona') {
  const u = ctx.ubicacion || {};
  let lugar;
  if (intent === 'feria_zona') {
    lugar = `en *${u.nombre}*`;
  } else {
    // Localidad más cercana de la lista de zonas (sin API externa)
    const km = (a, b) => {
      const rad = Math.PI / 180, dLat = (b.lat - a.lat) * rad, dLon = (b.lon - a.lon) * rad;
      const x = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin(dLon / 2) ** 2;
      return 12742 * Math.asin(Math.sqrt(x));
    };
    const cerca = json(cfg.feria_zonas, [])
      .map(z => ({ ...z, d: km(u, { lat: Number(z.lat), lon: Number(z.lon) }) }))
      .sort((a, b) => a.d - b.d)[0];
    lugar = cerca && cerca.d <= 40 ? `cerca de *${cerca.nombre}*` : `en *${Number(u.lat).toFixed(3)}, ${Number(u.lon).toFixed(3)}*`;
  }

  const s = resumen24h();
  const clima = data.length
    ? `🌡️ ${r(s.ahora.temperatura_c)}° ${s.ahora.condicion || ''} · ${r(s.tmin)}–${r(s.tmax)}° en 24 h\n` +
      `🌧️ ${fmtMm(s.mm)} mm (${r(s.prob)}%) · 💨 ${vientoTxt(s.ahora)}`
    : '⚠️ No pude obtener el clima de tu campo ahora.';

  const salida = [msg(
    `✅ Lote recibido ${lugar}\n${clima}\n📡 Radar: ${radarUrl(u.lat, u.lon)}\n\n` +
    `¿Otro lote? Enviame otra ubicación.`
  )];

  if (!registrado) {
    salida.push(msg(
      `🎁 *Promo ${feria}*\n` +
      `✅ 1 mes gratis · luego ${cfg.feria_precio}/mes\n` +
      `✅ Alertas de surazo, tormenta y viento\n` +
      `👥 3 amigos con tu código *${codigo}* = 1 mes más gratis`,
      BOTONES_FERIA
    ));
  }
  return salida;
}

// =====================================================
// 4) GUÍA DE LA FERIA: stand iAgro + sectores
// =====================================================
const sectores = json(cfg.feria_sectores, []);

if (intent === 'feria_guia') {
  return [msg(
    `🧭 *Guía ${feria}*\nElegí qué querés visitar 👇`,
    [
      { title: '⭐ Stand iAgro', value: 'stand' },
      ...sectores.slice(0, 9).map(s => ({ title: `${s.emoji} ${s.nombre}`, value: s.nombre }))
    ]
  )];
}

if (intent === 'feria_sector') {
  const sec = sectores.find(s => s.nombre === ctx.feria_sector) || {};
  const stands = sec.stands || [];
  const lista = stands.length
    ? stands.slice(0, 12).map(e => `• *${e.nombre}* — ${e.stand}`).join('\n')
    : `Estamos cargando los stands de este sector.\nPasá por el *Stand iAgro* (${cfg.feria_stand}) y te orientamos 😉`;
  return [msg(`${sec.emoji || '🧭'} *${sec.nombre || 'Sector'}*\n${lista}`, BOTONES_FERIA)];
}

if (intent === 'feria_stand') {
  return [msg(
    `⭐ *Stand iAgro — ${cfg.feria_stand}*\n` +
    `Conocé el pronóstico de tu lote y participá del sorteo de *${cfg.feria_premio}* 🎁\n` +
    `🗺️ ${mapsUrl(cfg.feria_stand_lat, cfg.feria_stand_lon)}`,
    BOTONES_FERIA
  )];
}

// =====================================================
// 5) CLIMA AHORA EN LA FERIA / INVITAR
// =====================================================
if (intent === 'feria_clima') {
  if (!data.length) return [msg('⚠️ No pude obtener el clima de la feria ahora. Probá en unos minutos 🙏')];
  const s = resumen24h();
  return [msg(
    `🌡️ *Ahora en la feria:* ${r(s.ahora.temperatura_c)}° ${s.ahora.condicion || ''}\n` +
    `🌧️ Lluvia próxima hora: ${r(s.proxima.probabilidad_precipitacion)}% · 💨 ${vientoTxt(s.ahora)}\n` +
    `📡 Radar: ${radarUrl(cfg.feria_lat, cfg.feria_lon)}`,
    otrosBotones('clima feria')
  )];
}

if (intent === 'feria_invitar') {
  // Dos mensajes: la instrucción y el texto limpio, listo para reenviar
  return [
    msg('👥 Reenviá este mensaje a tus amigos productores 👇'),
    msg(`Yo recibo el pronóstico de mi lote gratis en WhatsApp con iAgro 🌱 Escribí aquí 👉 ${cfg.feria_wa_link} y poné el código ${codigo}`)
  ];
}

return [msg('🤔 No entendí tu mensaje. Escribí *Menú* para ver las opciones.')];
